=== command_buffer.schema.json ===
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "merlin/bench_contract/command_buffer.schema.json",
  "title": "Merlin command buffer (experiment ABI v0.1)",
  "description": "Strict JSON Schema for the target-independent command buffer a package must emit. Mirrors merlin/schemas/command_buffer.schema.yaml but validated programmatically and fail-closed.",
  "type": "object",
  "required": ["abi_version", "target", "commands"],
  "properties": {
    "abi_version": {"type": "string"},
    "target": {"type": "string"},
    "backend": {"type": "string"},
    "tensors": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "required": ["shape", "dtype"],
        "properties": {
          "shape": {"type": "array", "items": {"type": "integer", "minimum": 1}, "minItems": 1},
          "dtype": {"type": "string", "enum": ["i8", "i16", "i32"]},
          "role": {"type": "string", "enum": ["input", "weight", "bias", "output"]}
        },
        "additionalProperties": false
      }
    },
    "commands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["opcode"],
        "properties": {
          "opcode": {
            "type": "string",
            "enum": ["RES_PACK", "MATMUL_RESIDENT", "MATMUL", "COMMIT", "EVICT", "VECTOR_MAP", "VREDUCE"]
          },
          "operands": {"type": "object", "additionalProperties": {"type": "string"}},
          "attributes": {
            "type": "object",
            "properties": {
              "layout": {"type": "string"},
              "epilogue": {"type": "array", "items": {"type": "string", "enum": ["bias_add", "bias", "requant", "acc_scale", "relu"]}},
              "output_dtype": {"type": "string", "enum": ["i8", "i16", "i32"]},
              "acc_scale": {"type": "number"},
              "requant_shift": {"type": "integer"},
              "combine": {"type": "string"},
              "activation": {"type": "array", "items": {"type": "string"}},
              "op": {"type": "string"}
            },
            "additionalProperties": true
          }
        },
        "additionalProperties": false
      }
    },
    "params": {"type": "object"},
    "metrics_requested": {"type": "array", "items": {"type": "string"}},
    "resources": {"type": "object"}
  },
  "additionalProperties": true
}
=== manifest.schema.json ===
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "merlin/bench_contract/manifest.schema.json",
  "title": "Out-of-tree target-backend package manifest (experiment ABI v0.1)",
  "description": "A package satisfying the experiment ABI declares this manifest. The runner validates it fail-closed before invoking anything. Same shape for Python and C++ packages — only `language`, `build`, and the entrypoint argv differ.",
  "type": "object",
  "required": ["artifact_type", "target", "language", "authoring", "integrity_exempt", "entrypoints", "commands"],
  "properties": {
    "artifact_type": {"const": "mlir_oot_target_backend"},
    "target": {"type": "string"},
    "package_id": {"type": "string"},
    "language": {"type": "string", "enum": ["python", "cpp"]},
    "authoring": {
      "type": "object",
      "required": ["mode"],
      "properties": {
        "mode": {"type": "string", "enum": ["hand_curated", "agent_generated_from_recipe", "agent_generated_from_rtl_facts", "deterministic_generated_from_spec"]},
        "author": {"type": "string"},
        "generated_by_agent": {"type": "boolean"}
      },
      "additionalProperties": true
    },
    "integrity_exempt": {
      "type": "boolean",
      "description": "true ONLY for the Merlin reference backend, which legitimately imports Merlin internals. Agent/independent packages MUST be false and pass the integrity scan."
    },
    "llvm": {
      "type": "object",
      "properties": {
        "version": {"type": "string"},
        "commit": {"type": "string"}
      }
    },
    "build": {
      "type": "object",
      "description": "Optional. If present, the runner builds the package before use (C++ gemmini-opt).",
      "required": ["command", "tool_output"],
      "properties": {
        "command": {"type": "array", "items": {"type": "string"}, "minItems": 1},
        "configure": {"type": "array", "items": {"type": "string"}},
        "tool_output": {"type": "string"}
      },
      "additionalProperties": false
    },
    "entrypoints": {
      "type": "object",
      "required": ["tool"],
      "properties": {"tool": {"type": "string"}},
      "additionalProperties": true
    },
    "commands": {
      "type": "object",
      "required": ["parse", "lower_interface_to_target", "emit_command_buffer", "lower_target_to_llvm"],
      "additionalProperties": {
        "type": "object",
        "required": ["argv"],
        "properties": {
          "argv": {"type": "array", "items": {"type": "string"}, "minItems": 1}
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": true
}

