            commands.append({
                "opcode": "COMMIT",
                "operands": {"src": acc, "dst": op.dst},
                "attributes": cattrs})
        elif isinstance(op, IR.Evict):
            commands.append({
                "opcode": "EVICT",
                "operands": {"handle": op.handle}})

    return {
        "abi_version": prog.abi_version or "0.1",
        "target": prog.target or "gemmini",
        "backend": "gemmini_oot_xdsl",
        "tensors": tensors,
        "commands": commands,
    }

